# Tools published only in the "full" MCP profile (Advanced building blocks). Descriptions follow
# one pattern: what it does, required inputs, what it returns, and how it differs from neighbours.
DESCRIPTIONS.update(
    {
        "dataset_import_snapshot": "Import one input file pinned by a calculation_plan (by input_index) as a dataset, re-checking its recorded SHA-256. Used inside calculation workflows; for new files use source_upload + dataset_import. Returns the dataset artifact.",
        "dataset_validate": "Run result_validate on one dataset artifact {id, revision}. Returns a job_id; the validation artifact lists PASS/FAIL/NOT RUN per check (NOT RUN when no validator exists for that kind). Does not modify the dataset.",
        "development_rank": "Rank up to 10 completed simulation_result cases by one metric (FOPT, FWPT, FWIT, WATER_CUT or FPR) at a report date, maximize or minimize, with optional metric constraints. Returns a comparison artifact. Ranks explicit variants only; not an optimizer and not a global optimum.",
        "ensemble_compare": "Statistics over an ensemble artifact from ensemble_run: per-case metric, min/max/mean/Q10/Q50/Q90 and pointwise bands on common report dates, with completed/failed counts. allow_partial controls failed cases. Returns a comparison artifact. For loose result lists use simulation_compare.",
        "ensemble_plan": "Read-only preview of an ensemble: explicit property realizations x schedules table, expected_case_count check and resume reuse. Nothing is queued. Run the same request with ensemble_run.",
        "ensemble_run": "Queue the ensemble previewed by ensemble_plan: one simulation_case_create + simulation_submit per realization x schedule row, failed rows kept and reported. resume_ensemble reruns only unfinished rows with the same inputs and seeds. Returns a parent job_id; result is an ensemble artifact.",
        "fault_create": "Create one planar fault from 3-64 XYZ points (metres, Z positive up) and a normal vector, relation offset_stratigraphy. Returns a fault artifact for model_build (GemPy). Single fault only; faulted models cannot be bridged to simulation.",
        "horizon_convert_domain": "Convert a time-domain interpretation (TWT) to depth with an explicit constant velocity_m_s or a monotonic 1D time_depth_table, origin_z_m and datum. Returns a depth dataset; the transform is stored with it. No velocity is inferred.",
        "interpretation_save": "Save manual horizon picks (inline, crossline, sample_index) on a seismic volume as a named interpretation; previous creates a new revision of an existing one. Picks stay in the volume's domain. Returns an interpretation artifact.",
        "properties_assign": "Assign constant phi, permeability_md, NTG, Sw and kz_ratio per zone id of a model from model_build. Returns a properties artifact for volumetrics_calculate, scenarios_run or simulation_case_create. Constants only; for spatial fields use properties_krige or properties_simulate.",
        "properties_krige": "Ordinary kriging (GSTools, exponential covariance) of phi or permeability_md in one zone from explicit conditioning points (positions, values, well_ids). Returns a new properties revision with leave-one-well-out holdout metrics. Deterministic; for random realizations use properties_simulate.",
        "properties_reference": "Pin an existing properties artifact {id, revision} as a workflow node output, checking that it exists and is of kind properties. Returns the artifact unchanged. Used only inside workflow_save graphs.",
        "properties_simulate": "Conditional random field (GSTools CondSRF) of phi or permeability_md in one zone from explicit conditioning points and a fixed seed. Returns a new properties revision with conditioning and holdout checks. One realization per call; same inputs and seed give the same field.",
        "scenarios_compare": "Compare STOIIP across several volumetrics artifacts (explicit variants): values, Q10/Q50/Q90 and ranking. Returns a comparison artifact. Static only; for simulation results use simulation_compare; the scenarios_run table already holds its own quantiles.",
        "scenarios_run": "Seeded Monte Carlo of STOIIP on a properties artifact from in-memory scalar distributions (constant, uniform, triangular) of phi, ntg, sw, bo and contact_z_m. Geometry is fixed. Returns a scenarios table with P90=Q10, P50=Q50, P10=Q90. For imported grids use uncertainty_monte_carlo.",
        "seismic_attribute": "Compute RMS amplitude over an odd sample window, or Hilbert envelope over full traces, on a seismic volume. Returns a new seismic artifact in the same geometry and domain. CPU or CUDA per execution.device_policy; CUDA results are checked against CPU.",
        "seismic_generate": "Generate a seeded synthetic 3D seismic cube (25 Hz Ricker reflector plus noise; shape, dt_seconds, velocity_m_s) for tests and demos. Returns a seismic artifact whose provenance and datum mark it synthetic. Not field data.",
        "seismic_import": "Import a small regular poststack 3D SEG-Y from an upload_id with explicit domain (twt/depth), sample unit, CRS, datum, endian and inline/crossline header bytes. Returns a seismic artifact. For large files use seismic_source_import (streaming, no upload).",
        "seismic_inspect": "Read-only metadata of one seismic artifact {id, revision}: geometry, domain, sample unit, CRS, files and checks. No samples are returned; use seismic_slice for data.",
        "seismic_slice": "Extract one inline, crossline or sample (time/depth) slice by index from a seismic volume. Returns a seismic_slice artifact with the 2D array, axes and units, suitable for results_export or the viewer.",
        "simulation_case_create": "Generate an OPM Flow case from a Cartesian properties artifact: profile waterflood, depletion or no_flow, explicit fluid, rates, BHP limits, start date and report days. Demo fluid values require demo_assumptions_accepted=true. Returns a simulation_case with deck, QC and grid mapping. For the user's own deck use simulation_deck_run.",
        "simulation_compare": "Compare simulation_result artifacts on common report dates: FOPT, FWPT, FWIT, WATER_CUT or FPR with documented interpolation, units and completed/failed counts. Returns a comparison artifact. For an ensemble artifact use ensemble_compare.",
        "simulation_results": "Read-only metadata of one simulation_result artifact {id, revision}: report dates, available vectors, units, solver status and files. Series are in the files; use simulation_snapshot for a 2D field view.",
        "simulation_snapshot": "Extract one 2D section (XY, XZ or YZ at an index) of pressure, sw, so or sg at a report step from a simulation_result. Returns a simulation_snapshot artifact with array, axes and units. No time interpolation.",
        "simulation_validate": "Run result_validate on one simulation case or result {id, revision} and its properties/model inputs. Returns a job_id; the validation artifact lists PASS/FAIL/NOT RUN per check, and checks without a validator for that kind are NOT RUN, never PASS.",
        "variogram_fit": "Fit an exponential variogram (GSTools) to explicit conditioning points of phi or permeability_md in one zone, then krige with the fitted model. Returns a properties revision with the fitted parameters, lag bins and holdout metrics. Needs at least 3 non-empty lag bins.",
        "workflow_cancel": "Cancel a running workflow_run or ensemble_run by job_id: stops running child jobs and keeps finished node outputs for resume. Returns the job record with status cancel_requested or cancelled.",
        "workflow_run": "Run a saved workflow artifact with optional run parameters; nodes execute in dependency order as durable child jobs. resume_run reuses node outputs whose input/config hashes still match. Returns a parent job_id; the result is a workflow_run artifact.",
        "workflow_save": "Save a DAG of up to 100 nodes {id, operation, arguments, depends_on}; arguments may reference {$node}, {$parameter} or pinned {id, revision}. Validates cycles, allowed operations and port kinds. Returns a workflow artifact for workflow_run. No code or shell execution.",
        "workflow_status": "Read-only state of a workflow_run or ensemble_run parent job by job_id: per-node status, child job ids, errors and result refs. Use job_logs for log lines.",
        "workflow_validate": "Read-only check of a saved workflow artifact {id, revision}: returns the topological node order and status valid, or the first cycle, unknown dependency or port-kind mismatch.",
    }
)
